/* ===== src/tokens.css ===== */
/* 草莓编辑部 | Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 * Third-party fonts and user-provided images retain their original rights/licenses.
 */

@font-face {
    font-family: "Huiwen-mincho";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/huiwenmincho-improved/HuiwenMincho-Improved-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Cormorant SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --se-red: #b72b2c;
    --se-red-deep: #842024;
    --se-red-soft: #d7645e;
    --se-cream: #f3eadb;
    --se-paper: #eee2cf;
    --se-paper-2: #e7d6bd;
    --se-ink: #29241e;
    --se-muted: #756b5e;
    --se-olive: #68704d;
    --se-forest: #1d291d;
    --se-line: rgba(132, 32, 36, 0.42);
    --se-shadow: 0 18px 44px rgba(38, 27, 20, 0.24);
    --se-radius: 2px;
    --se-font-body: "Huiwen-mincho", "Noto Serif SC", "Songti SC", serif;
    --se-font-display: "Cormorant SC", "Huiwen-mincho", serif;
    --se-topbar-block-size: 4.65rem;
    --topBarBlockSize: var(--se-topbar-block-size);
    --se-user-avatar-size: clamp(4.6rem, 6.5vw, 6rem);
    --se-strawberry-bg: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/strawberry-garden-background.png");
    --se-tool-01: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-01-new-chat-strawberry.png");
    --se-tool-02: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-02-save-ledger.png");
    --se-tool-03: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-03-world-bookmark.png");
    --se-tool-04: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-04-prompts-tag.png");
    --se-tool-05: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-05-search.png");
    --se-tool-06: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-06-memory-branch.png");
    --se-tool-07: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-07-notes-pencil.png");
    --se-tool-08: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-08-random-dice.png");
    --se-tool-09: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/tool-09-export-plane.png");
    --se-input-menu: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/input-menu.png");
    --se-input-wand: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/input-wand.png");
    --se-input-send: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bb24205d281cbac14d1e5f6d1d43b56072a7e0d0/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/input-send-plane.png");
}

body {
    color: var(--se-ink);
    background-color: var(--se-forest);
    font-family: var(--se-font-body);
}

#bg1,
#bg_custom {
    background-color: var(--se-forest);
    background-image: linear-gradient(rgba(15, 22, 14, 0.52), rgba(15, 22, 14, 0.78)), var(--se-strawberry-bg);
    background-size: cover;
    background-position: center;
}

#sheld,
.drawer-content,
.popup,
.popup-content,
.options-content,
#toast-container .toast {
    font-family: var(--se-font-body);
}

#chat :focus-visible,
#send_form :focus-visible,
#top-settings-holder :focus-visible,
.drawer-content :focus-visible,
.popup :focus-visible,
.options-content :focus-visible {
    outline: 2px solid var(--se-red);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    #chat .mes,
    #send_form,
    #top-settings-holder .drawer-toggle,
    .drawer-content .menu_button {
        transition: none !important;
        animation: none !important;
    }
}

/* ===== src/kernel/scrollbars.css ===== */
/* Global scrollbar appearance kernel — scrolling remains functional. */

::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* ===== src/kernel/tt-touch-compat.css ===== */
/* TT mobile WebView — decorations never intercept native open/close routing. */

@media (max-width: 700px), (pointer: coarse) {
    #top-settings-holder .drawer-toggle::before,
    #top-settings-holder .drawer-toggle::after,
    #send_form #options_button::before,
    #send_form #options_button::after,
    #send_form #extensionsMenuButton::before,
    #send_form #extensionsMenuButton::after,
    #send_form #send_but::before,
    #send_form #send_but::after {
        pointer-events: none;
    }
}

/* ===== src/chat-layout.css ===== */
/* W01 — main chat master: User portrait lead-in + Character manuscript */

#sheld {
    background: var(--se-paper);
    border-inline: 1px solid var(--se-line);
    box-shadow: var(--se-shadow);
}

#chat {
    color: var(--se-ink);
    background-color: var(--se-paper);
    background-image:
        linear-gradient(90deg, rgba(183, 43, 44, 0.035) 1px, transparent 1px),
        linear-gradient(rgba(132, 112, 83, 0.035) 1px, transparent 1px);
    background-size: 44px 44px, 44px 44px;
    padding: 0;
}

#chat .mes {
    position: relative;
    box-sizing: border-box;
    flex: 0 0 auto;
    width: 100%;
    min-height: auto;
    margin: 0;
    border-radius: 0;
    box-shadow: none;
    transition: background-color 160ms ease, color 160ms ease;
}

/* User keeps its real native portrait. Character is a full-width manuscript floor. */
#chat .mes[is_user="true"] {
    display: flex;
    align-items: start;
    gap: clamp(1rem, 2.6vw, 2.4rem);
    padding: clamp(1.35rem, 3vw, 2.8rem) clamp(1rem, 4vw, 4.2rem);
}

#chat .mes[is_user="true"] {
    color: var(--se-cream);
    background-color: var(--se-forest);
    background-image: linear-gradient(90deg, rgba(13, 20, 13, 0.9), rgba(13, 20, 13, 0.46) 64%, rgba(13, 20, 13, 0.74)), var(--se-strawberry-bg);
    background-size: cover;
    background-position: center;
    border-block: 4px solid var(--se-red);
}

#chat .mes[is_user="false"][is_system="false"] {
    display: block;
    padding: clamp(1.8rem, 4vw, 4.1rem) clamp(1rem, 5.2vw, 5.8rem) clamp(2.6rem, 5vw, 5.2rem);
    color: var(--se-ink);
    background: var(--se-paper);
    border-top: 1px solid var(--se-line);
}

#chat .mesAvatarWrapper {
    position: relative;
    z-index: 2;
    width: var(--se-user-avatar-size);
    min-width: 0;
    margin: 0;
    color: currentColor;
    text-align: center;
}

#chat .mesAvatarWrapper .avatar {
    position: relative;
    display: block;
    width: var(--se-user-avatar-size);
    height: var(--se-user-avatar-size);
    background-color: var(--se-paper-2);
    border: 1px solid currentColor;
    border-radius: 0;
    box-shadow: 0 0 0 4px rgba(183, 43, 44, 0.08), 0 10px 22px rgba(58, 45, 33, 0.16);
    overflow: hidden;
}

#chat .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

#chat .mesIDDisplay,
#chat .mes_timer,
#chat .tokenCounterDisplay {
    margin-top: 0.38em;
    color: currentColor;
    font-family: var(--se-font-display);
    font-size: 0.68em;
    letter-spacing: 0.06em;
    opacity: 0.64;
}

#chat .mes_block {
    flex: 1 1 auto;
    min-width: 0;
    width: auto;
    max-width: 76rem;
}

#chat .mes[is_user="false"][is_system="false"] > .mes_block {
    display: block;
    width: 100%;
    max-width: 76rem;
    margin-inline: auto;
}

/*
 * User explicitly requested no Character portrait. Keep the native wrapper and
 * its metadata in the DOM, but reduce only the portrait itself to a clipped,
 * non-interactive visual fallback. Message ID/timer remain as a small footnote.
 */
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
    position: absolute;
    left: clamp(1rem, 5.2vw, 5.8rem);
    bottom: 0.6rem;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 0.55em;
    width: auto;
    color: var(--se-muted);
    text-align: left;
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .avatar {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    border: 0;
    box-shadow: none;
    opacity: 0;
    pointer-events: none;
}

#chat .ch_name {
    gap: 0.75em;
    margin: 0 0 1em;
    padding: 0 0 0.75em;
    border-bottom: 1px solid currentColor;
}

#chat .mes[is_user="true"] .ch_name {
    border-bottom-color: rgba(243, 234, 219, 0.48);
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
    border-bottom-color: var(--se-line);
}

#chat .mes[is_user="true"] + .mes[is_user="false"][is_system="false"] {
    border-top: 4px solid var(--se-red);
    border-bottom: 1px solid var(--se-line);
}

#chat .mes[is_user="true"] + .mes[is_user="false"][is_system="false"] .ch_name::before {
    content: "CHARACTER  /  MANUSCRIPT";
    color: var(--se-red);
    font-family: var(--se-font-display);
    font-size: 0.7em;
    letter-spacing: 0.14em;
}

#chat .name_text {
    color: currentColor;
    font-family: var(--se-font-display);
    font-size: clamp(1.2em, 2vw, 1.85em);
    font-weight: 400;
    letter-spacing: 0.06em;
    text-shadow: none;
}

#chat .timestamp {
    color: currentColor;
    font-family: var(--se-font-display);
    font-size: 0.76em;
    letter-spacing: 0.08em;
    opacity: 0.7;
}

#chat .mes_buttons,
#chat .mes_edit_buttons {
    gap: 0.45em;
    color: currentColor;
}

#chat .mes_button,
#chat .mes_edit_buttons .menu_button {
    color: currentColor;
    text-shadow: none;
    filter: none;
    opacity: 0.44;
    transition: opacity 140ms ease, transform 140ms ease;
}

#chat .mes[is_user="false"][is_system="false"] .mes_buttons,
#chat .mes[is_user="false"][is_system="false"] .mes_edit_buttons,
#chat .mes[is_user="false"][is_system="false"] .mes_button,
#chat .mes[is_user="false"][is_system="false"] .mes_edit_buttons .menu_button {
    color: var(--se-red-deep);
    text-shadow: none;
    filter: none;
    opacity: 0.84;
}

#chat .mes:hover .mes_button,
#chat .mes:focus-within .mes_button,
#chat .mes:hover .mes_edit_buttons .menu_button,
#chat .mes:focus-within .mes_edit_buttons .menu_button {
    opacity: 0.96;
}

#chat .mes_button:hover,
#chat .mes_edit_buttons .menu_button:hover {
    transform: translateY(-1px);
}

#chat .mes_reasoning_details {
    margin: 1em 0 1.2em;
    color: var(--se-ink);
    background: rgba(231, 214, 189, 0.56);
    border: 1px solid var(--se-line);
    border-left: 3px solid var(--se-red);
    border-radius: 0;
    box-shadow: none;
    text-shadow: none;
    filter: none;
}

#chat .mes[is_user="true"] .mes_reasoning_details {
    color: var(--se-ink);
    background: rgba(231, 214, 189, 0.88);
    border-color: var(--se-line);
}

#chat .mes_reasoning_details .mes_reasoning_header {
    margin: 0;
    padding: 0.62em 2.2em 0.62em 0.9em;
    color: var(--se-red-deep);
    background: rgba(255, 250, 241, 0.78);
    border-bottom: 1px solid var(--se-line);
    border-radius: 0;
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
}

#chat .mes_reasoning_details .mes_reasoning {
    padding: 0.9em 1em 1em;
    color: var(--se-ink);
    background: transparent;
    box-shadow: none;
    text-shadow: none;
    filter: none;
}

#chat .mes[is_system="true"],
#chat .smallSysMes {
    margin: 0;
    padding: 0.9em clamp(1em, 4vw, 4em);
    color: var(--se-muted);
    background: var(--se-paper-2);
    border-block: 1px dashed var(--se-line);
    font-size: 0.88em;
}

#chat .mes.last_mes {
    --se-swipe-control-size: 2rem;
    --se-swipe-counter-width: 2.5rem;
    --se-swipe-control-gap: 0.35rem;
    padding-bottom: max(4.4rem, 6vw);
}

#chat .mes.last_mes .swipe_left,
#chat .mes.last_mes .swipeRightBlock {
    position: absolute;
    z-index: 4;
    bottom: 0.72rem;
    color: var(--se-red-deep);
}

#chat .mes.last_mes .swipe_left,
#chat .mes.last_mes .swipe_right {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: var(--se-swipe-control-size);
    height: var(--se-swipe-control-size);
    margin: 0;
    padding: 0;
    color: var(--se-red-deep);
    background: var(--se-paper-2);
    border: 1px solid var(--se-line);
    border-radius: 50%;
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 0.84;
    transition: color 140ms ease, background-color 140ms ease, opacity 140ms ease;
}

#chat .mes.last_mes .swipe_left {
    right: auto;
    left: calc(50% - (var(--se-swipe-counter-width) / 2) - var(--se-swipe-control-gap) - var(--se-swipe-control-size));
}

#chat .mes.last_mes .swipeRightBlock {
    right: auto;
    left: 50%;
    display: grid;
    grid-template-columns: var(--se-swipe-counter-width) var(--se-swipe-control-size);
    grid-template-areas: "counter next";
    align-items: center;
    gap: var(--se-swipe-control-gap);
    height: var(--se-swipe-control-size);
    transform: translateX(calc(var(--se-swipe-counter-width) / -2));
    opacity: 1;
}

#chat .mes.last_mes .swipe_right {
    position: static;
    grid-area: next;
    align-self: center;
}

#chat .mes.last_mes .swipes-counter {
    grid-area: counter;
    align-items: center;
    justify-content: center;
    width: var(--se-swipe-counter-width);
    min-width: var(--se-swipe-counter-width);
    height: var(--se-swipe-control-size);
    margin: 0;
    padding: 0;
    color: var(--se-muted);
    font-family: var(--se-font-display);
    font-size: 0.7em;
    line-height: 1;
    opacity: 0.78;
}

#chat .mes.last_mes .swipe_left:hover,
#chat .mes.last_mes .swipe_right:hover,
#chat .mes.last_mes .swipe_left:focus-visible,
#chat .mes.last_mes .swipe_right:focus-visible {
    color: var(--se-cream);
    background: var(--se-red);
    opacity: 1;
}

#chat .mes.last_mes .swipe_left:focus-visible,
#chat .mes.last_mes .swipe_right:focus-visible {
    outline: 2px solid var(--se-olive);
    outline-offset: 2px;
}

#chat .mes_media_wrapper,
#chat .mes_file_wrapper {
    max-width: 100%;
    overflow-x: auto;
}

/* ===== src/full-text.css ===== */
/* T02 + T07 — editorial long-form typography */

#chat .mes_text {
    min-width: 0;
    color: currentColor;
    font-family: var(--se-font-body);
    font-size: 1em;
    line-height: 1.88;
    letter-spacing: 0.035em;
    overflow-wrap: anywhere;
    text-shadow: none;
}

#chat .mes[is_user="true"] .mes_text {
    font-size: 1.08em;
    line-height: 1.7;
    letter-spacing: 0.055em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p {
    margin: 0 0 1.15em;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
    color: var(--se-red-deep);
    font-family: var(--se-font-display);
    font-weight: 400;
    letter-spacing: 0.06em;
    line-height: 1.32;
}

#chat .mes[is_user="true"] .mes_text h1,
#chat .mes[is_user="true"] .mes_text h2,
#chat .mes[is_user="true"] .mes_text h3,
#chat .mes[is_user="true"] .mes_text h4 {
    color: var(--se-cream);
}

#chat .mes_text h1 {
    font-size: 2em;
    margin: 0.45em 0 0.65em;
}

#chat .mes_text h2 {
    font-size: 1.55em;
    margin: 1.2em 0 0.58em;
}

#chat .mes_text h3,
#chat .mes_text h4 {
    font-size: 1.18em;
    margin: 1.1em 0 0.5em;
}

#chat .mes_text blockquote {
    margin: 1.35em 0;
    padding: 0.35em 0 0.35em 1.25em;
    color: var(--se-red-deep);
    background: transparent;
    border-left: 3px solid var(--se-red);
    font-size: 1.05em;
    font-style: normal;
}

#chat .mes[is_user="true"] .mes_text blockquote {
    color: var(--se-cream);
    border-left-color: var(--se-cream);
}

#chat .mes_text a {
    color: var(--se-red-deep);
    text-decoration-color: var(--se-red-soft);
    text-underline-offset: 0.18em;
}

#chat .mes[is_user="true"] .mes_text a {
    color: #ffe8d4;
}

#chat .mes_text hr {
    height: 0;
    margin: 2em 0;
    border: 0;
    border-top: 3px double var(--se-red);
}

#chat .mes_text ul,
#chat .mes_text ol {
    margin: 0.9em 0 1.2em;
    padding-inline-start: 1.7em;
}

#chat .mes_text code {
    color: var(--se-red-deep);
    background: rgba(132, 32, 36, 0.08);
    border: 1px solid rgba(132, 32, 36, 0.22);
    border-radius: 0;
}

#chat .mes_text pre {
    max-width: 100%;
    padding: 1.1em;
    color: var(--se-cream);
    background: #23281e;
    border-left: 4px solid var(--se-red);
    border-radius: 0;
    overflow: auto;
}

#chat .mes_text pre code {
    color: inherit;
    background: transparent;
    border: 0;
}

#chat .mes_text table {
    display: block;
    max-width: 100%;
    border-collapse: collapse;
    overflow-x: auto;
}

#chat .mes_text th,
#chat .mes_text td {
    padding: 0.65em 0.85em;
    border: 1px solid var(--se-line);
}

#chat .mes_text th {
    color: var(--se-cream);
    background: var(--se-red-deep);
    font-weight: 400;
}

#chat .mes_text img,
#chat .mes_text video {
    max-width: 100%;
    height: auto;
    border: 1px solid var(--se-line);
}

#chat .mes_text details {
    margin: 1em 0;
    padding: 0.75em 0.9em;
    background: rgba(104, 112, 77, 0.1);
