/* ===== src/windows/mobile.css ===== */
/* W14 — mobile single-column paired spread */

@media (max-width: 700px) {
    :root {
        --se-topbar-block-size: 4rem;
        --se-user-avatar-size: 3.7rem;
        --st-theme-mobile-reading-width: 100%;
        --st-theme-mobile-reading-padding: 0rem;
    }

    #top-settings-holder {
        box-sizing: border-box;
        height: var(--topBarBlockSize);
        min-height: var(--topBarBlockSize);
        padding-inline: 0.15rem;
        overflow: visible;
        scrollbar-width: none;
    }

    #top-settings-holder .drawer-toggle {
        box-sizing: border-box;
        width: calc((100dvw - 0.3rem) / 9);
        min-width: 0;
        max-width: calc((100dvw - 0.3rem) / 9);
        min-height: 3.55rem;
        margin-inline: 0;
        padding-inline: 0;
    }

    #top-settings-holder .drawer-toggle,
    #top-settings-holder .drawer-toggle:hover,
    #top-settings-holder .drawer-toggle:focus-within {
        transform: none;
        transition: color 140ms ease, background-color 140ms ease;
    }

    #top-settings-holder .drawer-toggle::before,
    #top-settings-holder .drawer-toggle:hover::before,
    #top-settings-holder .drawer-toggle:focus-within::before,
    #top-settings-holder .drawer-icon {
        transform: none;
        transition: none;
    }

    #top-settings-holder .drawer-toggle::before {
        inset: 0.62rem 0.32rem 0.58rem;
    }

    #top-settings-holder .drawer-toggle::after {
        left: 0.12rem;
        font-size: 0.43rem;
    }

    #chat .mes[is_system="false"] {
        display: flex;
        flex-direction: column;
        align-items: stretch;
    }

    #chat .mes[is_user="true"] {
        gap: 0.85rem;
        padding: 1.15rem 1rem 1.45rem;
    }

    #chat .mes[is_user="true"] > .mesAvatarWrapper {
        width: var(--se-user-avatar-size);
    }

    #chat .mes[is_user="false"][is_system="false"] {
        padding: 1.6rem 1rem 2.8rem;
    }

    #chat .mes[is_system="false"] > .mes_block,
    body.documentstyle #chat .mes[is_system="false"] > .mes_block {
        box-sizing: border-box;
        inline-size: 100%;
        min-inline-size: 0;
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: 0 !important;
    }

    #chat .mes[is_system="false"] > .mes_block > .mes_text,
    body.documentstyle #chat .mes[is_system="false"] > .mes_block > .mes_text {
        box-sizing: border-box;
        inline-size: min(100%, var(--st-theme-mobile-reading-width));
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: var(--st-theme-mobile-reading-padding) !important;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
        left: 1rem;
        bottom: 0.55rem;
    }

    #chat .name_text {
        font-size: 1.28em;
    }

    #chat .mes_text {
        font-size: 1em;
        line-height: 1.76;
    }

    #chat .mes[is_user="true"] .mes_text {
        font-size: 1em;
    }

    #chat .mes_buttons,
    #chat .mes_edit_buttons {
        opacity: 1;
    }

    #form_sheld {
        padding-bottom: env(safe-area-inset-bottom, 0);
    }

    #send_form {
        padding: 0.18rem 0.3rem max(0.18rem, env(safe-area-inset-bottom, 0px));
        background-color: var(--se-cream);
        background-image:
            linear-gradient(rgba(243, 234, 219, 0.58), rgba(243, 234, 219, 0.58)),
            url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/280abe83058c27f054288ecd8c9b602f86476f1a/assets/%E8%8D%89%E8%8E%93%E7%BC%96%E8%BE%91%E9%83%A8/input-strawberry-paper-v1.png");
        background-position: center;
        background-repeat: no-repeat;
        background-size: cover;
    }

    #send_form #nonQRFormItems {
        flex-flow: row nowrap;
        align-items: center;
        min-height: 2.65rem;
        gap: 0.15rem;
        padding: 0;
    }

    #send_form #leftSendForm,
    #send_form #rightSendForm {
        flex-flow: row nowrap;
        width: auto;
        min-width: 0;
    }

    #send_form #options_button,
    #send_form #extensionsMenuButton,
    #send_form #send_but,
    #send_form #mes_stop,
    #send_form .stscript_btn,
    #send_form #mes_continue,
    #send_form #mes_impersonate {
        flex-basis: 2.4rem;
        width: 2.4rem;
        height: 2.4rem;
        min-width: 2.4rem;
        min-height: 2.4rem;
    }

    #send_textarea {
        min-height: 2.55rem;
        padding: 0.4rem 0.55rem;
        font-size: 0.7rem;
        line-height: 1.35;
        background-color: rgba(255, 250, 241, 0.82);
    }

    #chat .mes[is_user="true"].last_mes,
    #chat .mes[is_user="false"][is_system="false"].last_mes {
        padding-bottom: 4.25rem;
    }

    #chat .mes.last_mes {
        --se-swipe-control-size: 1.9rem;
        --se-swipe-counter-width: 2.3rem;
    }

    #left-nav-panel .scrollableInner,
    #AdvancedFormatting .scrollableInner,
    #user-settings-block-content {
        padding: 0.75rem;
    }

    #user-settings-block-content {
